function esc(value) {
  return clean(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function clean(value) {
  return String(value).replace(/â€™/g, "'").replace(/â€œ/g, '"').replace(/â€/g, '"').replace(/â€“/g, "-").replace(/â€”/g, "-").replace(/â†’/g, "->").replace(/â†—/g, "->").replace(/Â·/g, "·").replace(/â€¦/g, "...");
}

