function getConfig(p) { return configs[p.slug] || hubConfig; }

function attrs(cfg, position) {
  return "data-cta-position=\"" + position + "\" data-page-slug=\"" + esc(cfg.slug) + "\" data-cta-variant=\"" + position + "-" + esc(cfg.lens).toLowerCase().replace(/[^a-z0-9]+/g, "-") + "\"";
}

function ctaBlock(cfg, position) {
  const c = cfg.cta;
  const headline = position === "top" ? c.topHeadline : position === "middle" ? c.middleHeadline : c.bottomHeadline;
  const body = position === "top" ? c.topBody : position === "middle" ? c.middleBody : c.bottomBody;
  const button = position === "top" ? c.topButton : position === "middle" ? c.middleButton : c.bottomButton;
  const trust = position === "top" ? c.topTrust : position === "middle" ? c.middleTrust : c.bottomTrust;
  return "<section class=\"cta-box cta-block cta-" + position + "\" " + attrs(cfg, position) + " aria-labelledby=\"cta-" + position + "-title\"><p class=\"cta-kicker\">" + (position === "top" ? "USE THE PAPERWORK, NOT THE PRESSURE" : position === "middle" ? "WHEN THE RISK BECOMES SPECIFIC" : "A CLEARER NEXT STEP") + "</p><h2 id=\"cta-" + position + "-title\">" + esc(headline) + "</h2><p>" + esc(body) + "</p><p class=\"cta-benefit\"><strong>HiddenFeeAI can help you review:</strong> " + esc(cfg.document) + " for " + esc(cfg.goal) + " through " + esc(cfg.lens) + " at the " + position + " review stage.</p><a class=\"cta\" href=\"" + ai + "\" target=\"_blank\" rel=\"noopener\" aria-label=\"" + esc(button) + " with HiddenFeeAI\" " + attrs(cfg, position + "-button") + ">" + esc(button) + " ↗</a><p class=\"cta-trust\">" + esc(trust) + "</p></section>";
}

function stickyFooter(footer, cfg) {
  const c = cfg.cta;
  return footer.replace(/<div class=\"sticky-cta-bar\">[\s\S]*?<\/a><\/div>/, "<div class=\"sticky-cta-bar\" data-cta-position=\"sticky\" data-page-slug=\"" + esc(cfg.slug) + "\" data-cta-variant=\"sticky-" + esc(cfg.lens).toLowerCase().replace(/[^a-z0-9]+/g, "-") + "\"><div class=\"sticky-text\"><span>" + esc(c.stickyLabel) + "</span></div><a href=\"" + ai + "\" class=\"sticky-btn\" target=\"_blank\" rel=\"noopener\" aria-label=\"" + esc(c.stickyAria) + "\" data-cta-position=\"sticky-button\" data-page-slug=\"" + esc(cfg.slug) + "\" data-cta-variant=\"sticky-button\">Review " + esc(c.stickyLabel) + " with HiddenFeeAI ↗</a></div>");
}

