function uniqueFaqItems(cfg) {
  const themes = cfg.sections.concat(cfg.terms, [cfg.lens + " follow-up evidence", cfg.lens + " decision timing"]).slice(0, 20);
  return themes.map(function(theme, i) {
    const focus = theme.toLowerCase();
    const q = i % 4 === 0 ? "What is the first document check for " + focus + " in " + cfg.lens + "?" : i % 4 === 1 ? "How can " + focus + " affect " + cfg.goal + "?" : i % 4 === 2 ? "What should I ask the dealer or lender about " + focus + "?" : "When should I pause the " + cfg.lens + " review over " + focus + "?";
    const a = i % 4 === 0 ? "Start with the page where " + focus + " is defined or priced, then compare it with the surrounding " + cfg.document + ". Record the amount, provider, term, and removal effect before relying on a verbal explanation. HiddenFeeAI can help locate the relevant wording, but the written agreement and current state rules control. Record the page number and date so a later revision cannot silently replace the copy you reviewed." : i % 4 === 1 ? focus.charAt(0).toUpperCase() + focus.slice(1) + " matters because it can change " + cfg.goal + " without changing the headline vehicle price. Calculate the before-and-after amount, identify who receives the money, and check whether the charge is optional, refundable, capped, or rolled into financing. Ask for a corrected copy if the math does not reconcile. A dated comparison is more useful than a payment-only claim." : i % 4 === 2 ? "Ask which document authorizes " + focus + ", whether it is required or optional, what it costs in cash and over the loan term, and what changes if you decline it. Request the answer on the buyer's order, finance contract, product agreement, or other controlling document rather than accepting a payment-only explanation. Write the requested correction beside the line before moving to another document." : "Pause when " + focus + " appears for the first time after the price or financing terms were already accepted, when a blank or changed number is involved, or when the provider will not give you a complete copy. Preserve the earlier version, ask for the reason in writing, and do not sign replacement terms until you can compare them. Keep each version in the same evidence folder.";
    return {q: q, a: a};
  });
}

function uniqueSections(cfg) {
  return cfg.sections.map(function(heading, i) {
    const term = cfg.terms[i % cfg.terms.length];
    const next = cfg.terms[(i + 1) % cfg.terms.length];
    const lead = i % 4 === 0 ? "The useful starting point for " + heading.toLowerCase() + " is the document, not the dealer's label. Locate " + term + " and record its exact amount, date, provider, and surrounding language." :
      i % 4 === 1 ? "A buyer evaluating " + term + " should create a before-and-after comparison. Write down the transaction without the item, then add it back and observe what changes in the cash price, amount financed, payment, finance charge, total of payments, coverage, or delivery condition." :
      i % 4 === 2 ? "The risk around " + term + " is often created by timing. It may appear after the vehicle price is accepted, after a credit application, or during a last-minute signature round. Keep the earlier quote, ask for a fresh copy, and mark the point where " + term + " entered the transaction." :
      "For " + cfg.lens + ", " + term + " should be tested against " + next + ". The two lines may be related, but they are not automatically substitutes. Ask whether they protect the same risk, go to the same recipient, have the same term, or use the same refund and claim rules.";
    const middle = "Use a precise question: “If I decline " + term + ", which exact numbers change, and where will that change appear?” Then ask for the answer on the buyer's order or the controlling agreement. For " + cfg.lens + ", keep the response tied to the page and line under review. If the response moves from required to recommended, or from included to removable, preserve both versions. The point is not to accuse a provider; it is to make the economic choice visible before the signature.";
    const close = "A sensible benchmark for this issue is an official regulator, lender disclosure, insurer quote, competing dealer quote, or the vehicle-specific agreement that governs the line. A benchmark cannot decide whether an item fits your circumstances, but it can expose an unexplained amount, a missing disclosure, or a comparison using different assumptions. Pair the benchmark with the vehicle, loan, state, and contract facts in front of you.";
    return "<section class=\"section topic-section\"><h2>" + esc(heading) + "</h2><p>" + lead + "</p><p>" + middle + "</p><div class=\"protip\"><strong>Checkpoint " + (i + 1) + ":</strong> Put " + esc(term) + " beside " + esc(next) + " and write the amount, recipient, term, and consequence of removing each one.</div><p>" + close + "</p></section>";
  }).join("") + decisionProtocol(cfg) + decisionAppendix(cfg) + extraParagraph(cfg);
}

function decisionProtocol(cfg) {
  return "<section class=\"section decision-protocol\"><h2>What to do when the paperwork disagrees</h2><p>Start by freezing the facts. Save the quote, the page that changed, the product or financing terms, and the message that brought the change to your attention. Write down the date, the person who explained it, and the exact words used to describe " + esc(cfg.terms[0]) + ". A short factual timeline is more useful than a general statement that the deal felt different.</p><p>Next, ask for one corrected version of the document that controls " + esc(cfg.lens) + ". Do not allow the correction to live only in a text message or an oral promise. Ask the provider to show the old number, the new number, the reason for the change, and the effect on " + esc(cfg.goal) + ". If the answer depends on state law, lender policy, insurance coverage, or a product administrator, ask for the responsible entity and a written contact.</p><p>Then choose the smallest safe action. It may be removing a product, correcting a VIN, requesting a new payoff, comparing a preapproval, delaying delivery, or obtaining professional advice. Small actions keep the negotiation precise. You do not have to decide whether the entire transaction is good or bad before deciding that one unexplained line is not ready to sign.</p><div class=\"callout\"><strong>Document-first script:</strong> “Please show me where " + esc(cfg.terms[0]) + " is defined, who receives the money, what happens if I decline it, and which total changes. I will review the corrected copy before deciding.”</div><p>Finally, compare the final packet after the issue is resolved. A corrected line can create a second arithmetic change elsewhere. Recheck the amount due, amount financed, payment, APR, term, product selection, and delivery condition that apply to this guide. If the revised copy cannot be reconciled, the safest conclusion is that the review is not complete.</p></section>";
}

function decisionAppendix(cfg) {
  return "<section class=\"section\"><h2>Prepare the evidence packet and act on the findings</h2><p>Put the first quote, revised quote, buyer's order, finance disclosure, the agreement for " + esc(cfg.terms[0]) + ", and every message explaining the change in a deliberate order. Remove full account numbers, driver's-license numbers, signatures, and unrelated personal details when they are not needed for the question. Keep the original files separately so a redaction does not become the only copy.</p><p>Label each page with what it is and when it was received. This makes a review faster because the question is not “what is this stack?” but “where did " + esc(cfg.terms[0]) + " enter, and what did it change?” If a document is missing, record that fact instead of filling the gap with an assumption. Missing pages, unreadable copies, and unsigned drafts should be treated as unresolved evidence.</p><h3>Sort findings into actions</h3><p>Put arithmetic or transcription issues in one group, optional choices and pricing comparisons in a second, and legal, lender, insurance, or dispute questions in a third. This sorting keeps a useful document review from becoming an overconfident conclusion. For this guide, the most useful output is a short list of questions tied to " + esc(cfg.terms[0]) + ", " + esc(cfg.terms[1]) + ", and the final " + esc(cfg.goal) + ". Take that list back to the responsible provider in writing, ask for the answer on the document that controls, and rerun the comparison.</p><p>The objective is a decision you can explain, not a pile of flags you cannot act on. If a line still cannot be reconciled after the provider has had a fair chance to explain it, preserve the record and consider pausing the transaction or obtaining qualified advice. The time spent making " + esc(cfg.lens) + " visible is part of the price protection.</p></section>";
}

function extraParagraph(cfg) {
  return "<section class=\"section\"><h2>Keep the comparison narrow and repeatable</h2><p>Do not let a review of " + esc(cfg.terms[0]) + " drift into an argument about every possible car-buying problem. Write one question, one requested correction, and one comparison that would change your decision. That discipline protects your time and makes the response easier for a dealer, lender, insurer, administrator, or agency to answer.</p><p>When the numbers are corrected, save the new version and note what changed. A clean record of " + esc(cfg.terms[0]) + " and " + esc(cfg.terms[1]) + " gives you a practical basis for negotiating, declining, or continuing. It also prevents a later conversation from resetting the facts to a vague memory of the original offer.</p></section>";
}

