function guideMain(p, cfg, header, footer) {
  const faqs = uniqueFaqItems(cfg);
  const takeaways = cfg.terms.slice(0, 5).map(function(t) { return "<li>" + esc(t) + " is a separate review question, not a reason to accept a bundled total.</li>"; }).join("");
  const rows = cfg.terms.slice(0, 7).map(function(term, i) { return "<tr><td><strong>" + esc(term) + "</strong></td><td>" + (i % 2 ? "Contract or disclosure term" : "Quote or transaction line") + "</td><td>" + (i % 3 === 0 ? "Who receives the money?" : i % 3 === 1 ? "What changes if it is removed?" : "Which document controls?") + "</td><td>" + (i % 2 ? "Written comparison and copy" : "Independent benchmark") + "</td></tr>"; }).join("");
  const glossary = cfg.terms.slice(0, 8).map(function(term, i) { return "<tr><td><strong>" + esc(term) + "</strong></td><td>A " + esc(cfg.lens) + " term to locate, define, and reconcile with " + esc(cfg.terms[(i + 1) % cfg.terms.length]) + ". The exact contract, disclosure, or state rule controls the final meaning.</td></tr>"; }).join("");
  const myths = [["The label tells me what the line means.", "The controlling document, recipient, term, and removal effect matter more than a sales label."], ["A lower payment proves I saved money.", "Payment can fall because a term grew, a balance moved, or products were financed. Compare the complete numbers."]];
  return "<a class=\"phase1-skip-link\" href=\"#main-content\">Skip to main content</a><div class=\"orb-accent\"></div>" + header + "<main id=\"main-content\" class=\"article-page\"><nav class=\"phase2-breadcrumb\" aria-label=\"Breadcrumb\"><a href=\"/\">Home</a><span class=\"phase2-separator\" aria-hidden=\"true\">/</span><a href=\"/car-dealer-fees\">Car Dealer Fees</a><span class=\"phase2-separator\" aria-hidden=\"true\">/</span><span aria-current=\"page\">" + esc(p.title) + "</span></nav><section class=\"hero\"><div class=\"eyebrow\">" + esc(p.tag) + " · FIELD GUIDE</div><h1><span>" + esc(p.title) + "</span></h1><p class=\"lede\">" + esc(p.short) + "</p><div class=\"meta\"><span class=\"pill\">Updated August 1, 2026</span><span class=\"pill\">Purpose: " + esc(cfg.goal) + "</span><span class=\"pill\">Topic: " + esc(cfg.lens) + "</span></div>" + ctaBlock(cfg, "top") + "</section><div class=\"jump\"><a href=\"#summary\">Summary</a><a href=\"#review\">Inspection path</a><a href=\"#examples\">Examples</a><a href=\"#red-flags\">Red flags</a><a href=\"#checklist\">Checklist</a><a href=\"#faq\">FAQs</a></div><div class=\"grid\"><article class=\"article\"><section id=\"summary\" class=\"section\"><h2>Executive summary</h2><div class=\"answer-first\"><strong>Short answer:</strong> " + esc(cfg.intent) + " The reliable review starts with " + esc(cfg.document) + ", labels each line, and measures whether it changes " + esc(cfg.goal) + ".</div><div class=\"key-takeaways\"><h3>Key takeaways</h3><ul>" + takeaways + "</ul></div><p>This guide is designed for the moment when " + esc(cfg.concern) + ". It does not assume that every fee is unlawful or that every product is worthless. It gives you a way to identify the economic choice, find the controlling document, compare an outside benchmark, and preserve a clean record of what was offered.</p><p>Use the sections in sequence when you are at a dealership. If time is short, read the answer-first box, the inspection matrix, the red flags, and the printable checklist. If the paperwork is already in your hands, use HiddenFeeAI as a second set of eyes after removing account numbers and other information you do not need to share.</p></section>" + uniqueSections(cfg) + "<section id=\"review\" class=\"section\"><h2>" + esc(cfg.lens) + " inspection matrix</h2><p>Use this table to turn a conversation into a reviewable record. Write the exact label, not a summary such as “fees,” and keep the version that was shown before and after negotiation.</p><div class=\"table-wrap\"><table><caption class=\"sr-only\">" + esc(cfg.lens) + " inspection matrix</caption><thead><tr><th>Item</th><th>Where it appears</th><th>Question to ask</th><th>Evidence to keep</th></tr></thead><tbody>" + rows + "</tbody></table></div>" + visual(cfg) + "<h3>Step-by-step inspection process</h3><ol class=\"process\"><li>Save the complete page before asking for changes.</li><li>Circle every number that affects " + esc(cfg.goal) + " and write its source.</li><li>Classify each line as vehicle price, government charge, dealer charge, optional product, trade equity, or credit cost.</li><li>Ask what changes if one line is removed and require the answer on a corrected written copy.</li><li>Compare the revised buyer's order with the finance contract and related product agreement.</li><li>Keep the signed packet, earlier quote, and follow-up messages together.</li></ol></section>" + ctaBlock(cfg, "middle") + "<section id=\"examples\" class=\"section\"><h2>Real-world examples and pressure patterns</h2><div class=\"fee-card\"><h3>Worked example</h3><p>" + esc(cfg.scenario) + "</p><p>The arithmetic is only the beginning. Ask which document authorizes each number, whether the recipient is the dealer, lender, government agency, insurer, or product administrator, and whether the buyer could obtain the same benefit elsewhere. A useful comparison uses the same vehicle, trade, down payment, loan term, and product choices.</p></div><div class=\"fee-card\"><h3>Common pressure pattern</h3><p>One number is introduced as a convenience, then the discussion moves to another document before the buyer can compare the total. The pattern is especially risky when a “required” product, changed trade payoff, or financing condition appears only after the buyer has invested time and emotionally committed to the vehicle.</p><p>Respond by asking for a complete copy, a written explanation, and a clean version with optional items removed. Do not sign a blank, incomplete, or replacement document merely to keep the process moving.</p></div><div class=\"callout warning\"><strong>Warning:</strong> " + esc(cfg.concern) + ". Treat a changing explanation, missing page, or pressure to sign immediately as a reason to pause and document.</div></section><section id=\"red-flags\" class=\"section\"><h2>Red flags to stop and question</h2><ul class=\"bullets\">" + cfg.terms.slice(0, 8).map(function(term, i) { return "<li><strong>" + esc(term) + ":</strong> " + (i % 2 ? "the amount or condition appears only after the core price was accepted" : "the provider cannot explain its purpose, recipient, term, or removal effect") + "</li>"; }).join("") + "</ul><h3>Consumer protection laws and oversight</h3><p>Consumer protection in an auto transaction may involve federal rules, state dealer and unfair-practice laws, lending disclosures, insurance or service-contract regulation, and motor-vehicle title and fee rules. Which rule applies depends on the document, the business making the representation, the state, and the timing. Use official agency sources for current requirements, preserve evidence, and seek qualified advice for a dispute rather than treating a general guide as a legal conclusion.</p><ul class=\"refs\"><li><a href=\"https://www.ftc.gov/consumer-advice\" target=\"_blank\" rel=\"noopener\">Federal Trade Commission consumer guidance</a></li><li><a href=\"https://www.consumerfinance.gov/consumer-tools/auto-loans/\" target=\"_blank\" rel=\"noopener\">Consumer Financial Protection Bureau auto-loan resources</a></li><li><a href=\"https://www.naag.org/find-my-ag/\" target=\"_blank\" rel=\"noopener\">State attorney general directory</a></li></ul></section><section class=\"section\"><h2>Statistics and signals worth knowing</h2><div class=\"stat\"><b>1 line</b><span>can change the amount financed</span></div><div class=\"stat\"><b>4 numbers</b><span>APR, amount financed, finance charge, total of payments</span></div><div class=\"stat\"><b>2 copies</b><span>keep the signed packet in separate places</span></div><p>Statistics should be used carefully. A survey, enforcement matter, or complaint count may show a risk signal, but it cannot tell you whether a particular line in your contract is permitted or worthwhile. The most reliable measurement for your deal is a before-and-after comparison: record the total before the issue appears, record the final total, and identify the exact line that explains the difference.</p></section><section class=\"section\"><h2>Negotiation tips and money-saving checklist</h2><p>Negotiate the decision that belongs to this guide. Ask for the relevant document, name the line, request the corrected number, and compare the result with a credible alternative. Do not accept a lower payment as proof of savings until the term, amount financed, APR, finance charge, and total of payments are written down.</p><ul class=\"checklist\">" + cfg.terms.map(function(term) { return "<li>Ask for " + esc(term) + " in writing and keep the version before and after negotiation.</li>"; }).join("") + "</ul></section><section id=\"checklist\" class=\"section\"><div class=\"printable\"><h2>Printable " + esc(cfg.lens) + " checklist</h2><h3>Before I sign, I verified:</h3><ul class=\"checklist\">" + cfg.terms.map(function(term) { return "<li>" + esc(term) + " is identified, priced, and connected to the correct document.</li>"; }).join("") + "</ul><p class=\"disclaimer\">Print for personal use. Confirm current state-specific requirements with the relevant agency.</p></div></section><section id=\"faq\" class=\"section\"><h2>Frequently asked questions</h2>" + faqs.map(function(x, i) { return "<details " + (i === 0 ? "open" : "") + "><summary>" + esc(x.q) + "</summary><p>" + esc(x.a) + "</p></details>"; }).join("") + "</section><section class=\"section\"><h2>Myth vs. fact</h2><div class=\"myth\">" + myths.map(function(x) { return "<div><b>Myth</b>" + esc(x[0]) + "</div><div><b>Fact</b>" + esc(x[1]) + "</div>"; }).join("") + "</div></section><section class=\"section\"><h2>Glossary</h2><div class=\"table-wrap\"><table><tbody>" + cfg.terms.slice(0, 8).map(function(term, i) { return "<tr><td><strong>" + esc(term) + "</strong></td><td>A " + esc(cfg.lens) + " term to locate and reconcile with " + esc(cfg.terms[(i + 1) % cfg.terms.length]) + ". The exact contract, disclosure, or state rule controls the final meaning.</td></tr>"; }).join("") + "</tbody></table></div></section><section class=\"section\"><h2>Related resources and contract review tools</h2><div class=\"related\">" + relatedLinks(p) + "<a href=\"/ai-contract-review\">Broader contract review authority</a><a href=\"/hidden-fee-industry-guide\">Hidden fee industry guide</a><a href=\"/ai-construction-contract-review\">Construction contract review hub</a><a href=\"/ai-contract-review-software\">SaaS contract review resource</a></div>" + ctaBlock(cfg, "bottom") + "</section></article><aside class=\"toc\"><strong>On this page</strong><a href=\"#summary\">Executive summary</a><a href=\"#review\">Inspection process</a><a href=\"#examples\">Examples and pressure patterns</a><a href=\"#red-flags\">Red flags</a><a href=\"#checklist\">Printable checklist</a><a href=\"#faq\">FAQs</a><a href=\"" + ai + "\" target=\"_blank\" rel=\"noopener\" data-cta-position=\"toc\" data-page-slug=\"" + esc(p.slug) + "\" data-cta-variant=\"toc-review\">Review this document with HiddenFeeAI ↗</a></aside></div></main>" + stickyFooter(footer, cfg) + trackingScript();
}

function remapHead(html, p, cfg, faqs) {
  let head = (html.match(/<head>[\s\S]*?<\/head>/i) || [""])[0];
  head = clean(head);
  head = head.replace(/<script type=\"application\/ld\+json\">[\s\S]*?<\/script>/g, "");
  return head.replace("</head>", schemaFor(p, cfg, faqs) + "</head>");
}

function remediateGuide(html, p, sharedHeader, sharedFooter) {
  const cfg = Object.assign({}, getConfig(p), {slug: p.slug});
  return "<!doctype html><html lang=\"en\">" + remapHead(html, p, cfg, uniqueFaqItems(cfg)) + "<body>" + varyCommonParagraphs(guideMain(p, cfg, sharedHeader, sharedFooter), cfg) + "</body></html>";
}

function hubFaq() {
  return [
    {q: "Where should I start?", a: "Choose the guide that matches the document or conversation in front of you, then compare written totals and terms."},
    {q: "What documents can HiddenFeeAI review?", a: "Quotes, purchase agreements, auto-loan contracts, product agreements, and related paperwork can be organized for a second set of eyes."},
    {q: "Are dealer add-ons required?", a: "Many add-ons are optional; ask for the claimed legal or lender requirement in writing and request a clean quote."},
    {q: "What should I compare besides payment?", a: "Compare selling price, fees, APR, amount financed, term, finance charge, and total of payments."},
    {q: "What if financing changes after delivery?", a: "Preserve the signed packet, ask for written lender information, and do not sign replacement terms without comparing them."}
  ];
}

